/* 🍡 糯嘰原生 —— 月曆出廠外觀（可直接在此微調） */
:root {
    /* 頁面 */
    --cal-page-bg: var(--mochi-bg);
    --cal-ink: #2c3e50;

    /* 月份標題 */
    --cal-title-color: #2c3e50;
    --cal-title-size: 1.5rem;
    --cal-title-weight: 800;
    --cal-title-letter-spacing: -0.5px;

    /* 星期列 */
    --cal-week-color: #95a5a6;
    --cal-week-size: 0.85rem;
    --cal-week-weight: 600;

    /* 日格：糯米糰不規則圓 + 毛玻璃 + 左上高光 */
    --cal-grid-gap: 10px;
    --cal-day-bg: rgba(255, 255, 255, 0.6);
    --cal-day-radius: 50% 50% 48% 48% / 50% 50% 45% 45%;
    --cal-day-border: 1px solid rgba(255, 255, 255, 0.8);
    --cal-day-shadow: inset 0 2px 4px rgba(255, 255, 255, 1), 0 4px 10px rgba(0, 0, 0, 0.03);
    --cal-day-backdrop-filter: blur(10px);
    --cal-day-shine: rgba(255, 255, 255, 0.8);
    --cal-daynum-color: #2c3e50;
    --cal-daynum-size: 1.1rem;
    --cal-daynum-weight: 700;

    /* 今天：粉色糖球 */
    --cal-today-bg: linear-gradient(135deg, #ff8fab 0%, #ffb6c1 100%);
    --cal-today-color: #fff;
    --cal-today-shadow: 0 8px 20px rgba(255, 143, 171, 0.4);

    /* 今日次元重疊卡片 */
    --cal-card-bg: rgba(255, 255, 255, 0.6);
    --cal-card-radius: 24px;
    --cal-card-border: 1px solid rgba(255, 255, 255, 0.6);
    --cal-card-shadow: 0 4px 20px rgba(0, 0, 0, 0.05);
    --cal-card-backdrop-filter: blur(20px);
    --cal-card-title-color: #2c3e50;
    --cal-item-ai-bg: #FFF9C4;
    --cal-item-user-bg: #D1EAFA;
    --cal-item-todo-bg: #D4EDDA;

    /* 底欄 + 加號按鈕 */
    --cal-nav-bg: rgba(255, 255, 255, 0.75);
    --cal-nav-radius: 24px 24px 0 0;
    --cal-nav-shadow: 0 -2px 20px rgba(0, 0, 0, 0.03);
    --cal-nav-backdrop-filter: blur(20px);
    --cal-nav-active-color: #ff8fab;
    --cal-fab-bg: linear-gradient(135deg, #ff8fab 0%, #ff5e95 100%);
    --cal-fab-color: #fff;
    --cal-fab-radius: 24px;
    --cal-fab-border: 4px solid #fff;
    --cal-fab-shadow: 0 10px 25px rgba(255, 94, 149, 0.4);

    /* 貼紙 */
    --cal-sticker-marker-bg: linear-gradient(135deg, #FFF9E6, #FFE082);
    --cal-sticker-heart-bg: linear-gradient(135deg, #FFE5EC, #FFB7C5);

    /* 行程表 / 影集 */
    --cal-now-pill-color: #ff8fab;
    --cal-now-pill-border: 2px solid #ff8fab;
    --cal-agenda-line-color: #ff8fab;
    --cal-agenda-dot-border: 2px solid #ff8fab;
    --cal-memory-title-color: #8D6E63;
    --cal-memory-title-border: 3px dashed #FFCCBC;
    --cal-memory-title-shadow: 2px 4px 0px #FFAB91;
}

/* ---------- 主容器 ---------- */
#book-nook-screen {
  background: #f3f3f3;
  color: #ffffff;
}

/* ---------- 顶栏 ---------- */
.nook-head {
  background:#4c917c;
  border-bottom:none;
  box-shadow:none;
}

/* 返回和加号 按钮 */
.nook-head .nook-icon-btn {
  color: #ffffff;
  background: transparent;
}

.nook-head .nook-icon-btn:hover {
  color: #57796e;
}

/* 标题 "一起看" */
.nook-head .nook-head-title {
  color: #ffffff;
  text-shadow:none;
}

.nook-head .nook-head-title svg {
  color: #ffffff;
}

.nook-head .nook-head-title svg path:first-child {
  fill: #8a2121;
  stroke: none;
}

/* "我" 按钮 */
.nook-head .nook-user-wrap .nook-user-btn {
  background: rgba(87, 121, 110, 0.2);
  border: 1px solid #ffffff;
  color: #ffffff;
}

.nook-head .nook-user-wrap .nook-user-btn:hover {
  background: rgba(87, 121, 110, 0.4);
  border-color: #57796e;
  color: #57796e;
}

.nook-head .nook-user-btn svg {
  color: #ffffff;
}

.nook-head .nook-user-btn:hover svg {
  color: #57796e;
}

/* ---------- 内容区 ---------- */
.nook-content {
  background: #f3f3f3;
}

/* ---------- 过滤栏 ---------- */
/* 过滤栏容器 */
.nook-filter-bar {
  background: #ffffff;
  padding: 16px;
  border-radius: 0 0 12px 12px;
}

/* 搜索框 */
.nook-search-box {
  background: #f7f7f7;
  border: 1.5px solid #c2c2c2;
  border-radius: 30px;
}

.nook-search-box:focus-within {
  border-color: #57796e;
}

.nook-search-box .nook-search-icon {
  color: #c2c2c2;
  opacity: 1;
  stroke-width: 3;
}

.nook-search-box .nook-search-input {
  background: transparent;
  color: #505050;
}

.book-nook-screen .nook-search-box .nook-search-input::placeholder {
	color: #c2c2c2;
}

.book-nook-screen .nook-search-box .nook-search-input {
  outline: none !important;
  border-color: transparent !important;
  box-shadow: none !important;
}

.nook-search-box .nook-search-input:focus {
  outline: none !important;
  box-shadow: none !important;
}

.nook-search-box .nook-search-input:hover {
  outline: none !important;
  box-shadow: none !important;
}

/* 标签按钮 "阅读中" 和 "已完结" */
.nook-tabs .nook-tab-btn.active {
  background: #e8f0ec !important;
  color: #57796e !important;
  box-shadow: inset 0 -2px 0 #57796e !important;
  text-shadow: none !important;
}

.nook-tabs .nook-tab-btn {
  background: #f7f7f7;
  color: #888888;
  border: none;
}

.nook-tabs .nook-tab-btn:hover {
  background: #e8f0ec;
  color: #57796e;
}

.nook-tab-btn svg {
  color: currentColor;
}

/* ---------- 加载提示 ---------- */
.nook-loading {
  color: #888888;
  animation: pulse-text 1.8s ease-in-out infinite;
}

/* 整个加载容器 */
.nook-import-busy {
  color: #4c917c;
}

/* SVG 图标 */
.nook-import-busy svg {
  color: #4c917c;
}

/* 文字 */
.nook-import-busy p {
  color: #4c917c;
}

/* ========== 导入弹窗 ========== */

/* 弹窗遮罩  */
.nook-modal-overlay {
  background: rgba(0, 0, 0, 0.3);
}

/* 加号弹出菜单 */
.nook-add-menu,
.nook-user-menu {
  background: #ffffff;
  border: none;
  border-radius: 12px;
  box-shadow: 0 10px 20px #505050;
}

.nook-add-menu button,
.nook-user-menu button {
  color: #505050;
  background: transparent;
  transition: background 0.2s, color 0.2s;
}

.nook-add-menu button:hover,
.nook-user-menu button:hover {
  background: #e8f0ec;
  color: #4c917c;
}

.nook-add-menu button svg,
.nook-user-menu button svg {
  color: #4c917c;
}

/* 弹窗主体 */
.nook-modal {
  background: #ffffff;
  border-radius: 20px;
  border: none;
  outline: none !important;
  box-shadow: 0 10px 20px #505050;
}

/* 弹窗头部 */
.nook-modal-head {
  border-bottom: 1px solid #4c917c;
}

.book-nook-screen .nook-modal-head svg {
  color: #4c917c;
}

.nook-modal-title {
  color: #4c917c;
}

/* 导入选项容器 */
.nook-import-choices {
  background: #ffffff;
  box-shadow: none;
}

/* 单个导入选项 */
.nook-import-choice {
  background: #f3f3f3;
  border: 1px solid #c2c2c2;
  border-radius: 14px;
  transition: background 0.2s, border-color 0.2s, box-shadow 0.2s;
  box-shadow: none;
}

.nook-import-choice:hover {
  background: #e8f0ec;
  border: none;
}

.nook-import-choice svg {
  color: #4c917c;
}

.nook-import-choice-title {
  color: #505050;
}

.nook-import-choice-sub {
  color: #c2c2c2;
}

/* 回忆录用户行 */
.nook-user-chip {
  color: #505050;
  background: #f3f3f3;
  border: 1px solid #c2c2c2;
  border-radius: 12px;
  transition: all 0.25s ease;
  outline: none;
}

/* 点击状态 */
.nook-user-chip:active {
  background: #e8f0ec;
  border-color: #57796e;
  transform: scale(0.96);
}

/* 选中/激活状态 */
.nook-user-chip.active {
  background: #e8f0ec;
  border-color: #4c917c;
  color: #505050;
}

/* 回忆录行 */
.nook-memoir-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: #ffffff;
  border-radius: 12px;
  border: 1px solid #e8f0ec;
  margin-bottom: 8px;
  transition: all 0.3s ease;
}

.nook-memoir-row:hover {
  border-color: #57796e;
}

.nook-memoir-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.nook-memoir-title {
  font-size: 16px;
  font-weight: 600;
  color: #264a3f;
}

.nook-memoir-sub {
  font-size: 12px;
  color: #57796e;
}

.nook-memoir-acts {
  display: flex;
  gap: 10px;
}

.nook-memoir-acts button {
  padding: 6px 18px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 500;
  border: none;
  cursor: pointer;
  transition: all 0.3s ease;
}

.nook-memoir-gen {
  background: #57796e;
  color: #ffffff;
}

.nook-memoir-gen:hover {
  background: #264a3f;
  transform: translateY(-1px);
}

.nook-memoir-gen:active {
  transform: translateY(0);
}

.nook-memoir-sync {
  background: #e8f0ec;
  color: #57796e;
  font-weight: bold;
}

.nook-memoir-sync:hover:not(:disabled) {
  background: #8fb6a5;
  transform: translateY(-1px);
}

.nook-memoir-sync:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none !important;
  box-shadow: none !important;
}

/* ---------- 回忆小说弹窗主体（玻璃效果） ---------- */
.hl-modal.glass.hl-novel-reader {
  background: #ffffff;
  border-radius: 20px;
  display: flex;
  flex-direction: column;
  max-height: 90vh;
  overflow: hidden;
}

.hl-modal {
  border: none;
}

/* 弹窗头部 */
.hl-modal-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  border-bottom: 1px solid #4c917c;
  flex-shrink: 0;
}

/* 标题文字 */
.hl-modal-title {
  flex: 1;
  font-size: 18px;
  font-weight: 600;
  color: #4c917c;
  text-align: start;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* 头部按钮通用 */
.hl-modal-back,
.hl-modal-close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: none;
  background: transparent;
  color: #4c917c;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.hl-modal-back:hover,
.hl-modal-close:hover {
  background: transparent;
  color: #57796e;
}

/* 内容区（空白状态） */
.hl-novel-toc {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
}

.hl-showcase-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 20px;
  text-align: center;
}

.hl-showcase-empty svg {
  color: #4c917c;
  opacity: 0.6;
}

.hl-showcase-empty p {
  color: #c2c2c2;
  font-size: 14px;
  line-height: 1.6;
  max-width: 280px;
  margin: 0;
}

/* 底部操作区 */
.hl-novel-foot {
  border-top: 1px solid #c2c2c2;
  border-radius: 12px 12px 0 0;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  flex-shrink: 0;
  background: #ffffff;
}

/* 文风设定面板 */
.hl-novel-style {
  display: flex;
  flex-direction: column;
  gap: 10px;
  border: 1px solid #c2c2c2;
}

/* 小标题 */
.hl-novel-style-label {
  font-size: 13px;
  font-weight: 600;
  color: #4c917c;
  opacity: 1;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* 选项标签组 */
.hl-novel-style-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

/* 单个选项标签 */
.hl-novel-chip {
  padding: 6px 14px;
  font-size: 13px;
  font-weight: 500;
  color: #505050;
  background: #ffffff;
  border: 1px solid rgba(76,145,124,0.5);
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;
  white-space: nowrap;
}

.hl-novel-chip:hover {
  background: #e8f0ec;
  border-color: #4c917c;
  color: #505050;
}

/* 文风选项选中态 */
.hl-novel-chip.active,
.hl-novel-style-chips .hl-novel-chip.selected {
  background: #e8f0ec;
  border-color: #4c917c;
  color: #264a3f;
}

/* 自定义文风输入框 */
.hl-novel-style-input {
  padding: 10px 14px;
  font-size: 13px;
  color: #505050;
  background: #f3f3f3;
  border: 1px solid rgba(76,145,124,0.5);
  border-radius: 10px;
  resize: vertical;
  font-family: inherit;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.hl-novel-style-input::placeholder {
  color: #c2c2c2;
}

.hl-novel-style-input:focus {
  border-color: #4c917c;
}

.book-nook-screen .hl-novel-foot .hl-novel-style .hl-novel-style-save-row .hl-novel-style-name:focus {
  border-color: rgba(76, 145, 124, 0.5) !important;
}

/* 整体行容器 */
.hl-novel-style-save-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: none;
}

/* 输入框 */
.hl-novel-style-name,
.hl-novel-style-name:focus,
.hl-novel-style-name:focus-visible,
.hl-novel-style-name:active {
  flex: 1;
  font-size: 13px;
  color: #505050;
  background: #f3f3f3;
  border: 1px solid rgba(76,145,124,0.5);
  border-radius: 10px;
  outline: none !important;
  outline-style: none !important;
  box-shadow: none !important;
  font-family: inherit;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.book-nook-screen .hl-novel-foot .hl-novel-style .hl-novel-style-input:focus {
  border-color: rgba(76, 145, 124, 0.5) !important;
}

.hl-novel-style-name::placeholder {
  color: #505050;
  font-size: 13px;
}

.hl-novel-style-name:focus {
  border: 1px solid rgba(76,145,124,0.5);
  box-shadow: none !important;
}

/* 收藏按钮 */
.hl-novel-chip.save {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 500;
  color: #4c917c;
  background: #e8f0ec !important;
  border: 1px solid rgba(76,145,124,0.5);
  border-radius: 10px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
  outline: none;
}

.hl-novel-chip.save:hover {
  background: #8fb6a5;
  border-color: #4c917c;
  transform: translateY(-1px);
}

.hl-novel-chip.save:active {
  transform: translateY(0);
  background: #8fb6a5;
}

/* 通用按钮 */
.hl-novel-style .hl-novel-btn {
	display: flex !important;
	width: 100% !important;
	box-sizing: border-box !important;
}

.hl-novel-btn {  
  padding: 10px 20px;
  font-size: 12px;
  font-weight: 800;
  color: #ffffff;
  background: #57796e;
  border: 1px solid #57796e;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.25s ease;
  outline: none;
  display: inline-flex;
  align-items: center;
  align-self: center;
  justify-content: center;
  gap: 6px;
}

.book-nook-screen .hl-novel-btn svg {
  flex-shrink: 0;
  display: inline-block;
  vertical-align: middle;
  color: #ffffff !important;
  stroke: #ffffff !important;
}

.hl-novel-btn.primary {
	display: flex !important;
	width: 100% !important;
	box-sizing: border-box !important;
}

.hl-novel-free-hint {
	color:#c2c2c2 !important;
}

/* 开关按钮整体 */
.hl-novel-toggle {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
  background: #ffffff;
  border: 1px solid rgba(76,145,124,0.5);
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.25s ease;
  outline: none;
  width: 100%;
  text-align: left;
  color: #505050;
}

.hl-novel-toggle.on {
  background: rgba(76,145,124,0.3);
  border: 1px solid #4c917c;
}

/* 开关圆点 */
.hl-novel-toggle-dot {
  flex: none;
  width: 34px;
  height: 20px;
  border-radius: 20px;
  background: rgba(76,145,124,0.2);
  position: relative;
  transition: all 0.25s ease;
  margin-top: 2px;
}

.hl-novel-toggle-dot.on {
  background: rgba(76,145,124,0.8);
}

/* 标题 */
.hl-novel-toggle-title {
  font-size: 13px;
  font-weight: 600;
  color: #264a3f;
  line-height: 1.4;
}

/* 描述 */
.hl-novel-toggle-desc {
  font-size: 11px;
  color: #505050;
  line-height: 1.4;
}

/* ========== 日期范围选择行 ========== */
/* 日期输入框 */
.hl-novel-date,
.hl-novel-date:focus,
.hl-novel-date:focus-visible {
  font-size: 13px;
  color: #505050;
  background: #f3f3f3;
  border: 1px solid rgba(76, 145, 124, 0.5) !important;
  border-radius: 10px;
  outline: none !important;
  box-shadow: none !important;
  font-family: inherit;
  transition: border-color 0.2s;
}

/* 箭头分隔符 */
.hl-novel-range-sep {
  opacity: 1;
  color: #2b2b2b;
}

.hl-novel-ch-title {
	color: #264a3f;
}

.hl-novel-fontbar button {
    border: 1px solid rgba(76, 145, 124, 0.5);
    background: #e8f0ec;
    color: #4c917c;
    border-radius: 8px;
    padding: 2px 8px;
    font-size: 12px;
    cursor: pointer;
}

.hl-novel-toc-item {
    display: flex;
    align-items: baseline;
    gap: 10px;
    padding: 10px 12px;
    border-radius: 12px;
    border: 1px solid rgba(76, 145, 124, 0.5);
    background: #f3f3f3;
    cursor: pointer;
    text-align: left;
}

.hl-novel-toc-num {
    font-size: 12px;
	color: #4c917c;
    opacity: .8;
}

.hl-novel-toc-title {
    font-size: 14px;
    font-weight: 600;
	color: #264a3f;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* ========== 皮肤保存行 ========== */
/* 整体行容器 */
.nook-skin-saverow {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
}

/* 输入框 */
.nook-skin-saverow input {
  flex: 1;
  padding: 8px 14px;
  font-size: 13px;
  color: #505050;
  background: #f3f3f3;
  border: 1px solid rgba(76, 145, 124, 0.5);
  border-radius: 10px;
  outline: none !important;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.nook-skin-saverow input::placeholder {
  color: #c2c2c2;
}

.nook-skin-saverow :focus {
  border-color: none !important;
}

/* 保存按钮 */
.nook-skin-saverow .nook-pick-start {
  margin: 0 !important;
  width: auto !important;
  padding: 8px 20px !important;
  font-size: 14px;
  font-weight: 500;
  text-shadow: none;
  background: #57796e;
  border: 1px solid #57796e;
  border-radius: 10px;
  color: #ffffff;
  cursor: pointer;
