  z-index:1;
}

/* 杯柄 */
.nook-cup-handle {
  position: absolute;
  top:7px;
  right: -5px;
  transform: translateY(-50%);
  width: 7px;
  height: 11px;
  border: 2px solid #57796e;
  border-left: none;
  border-radius: 0 45% 45% 0;
}

/* 杯碟 */
.nook-cup-saucer {
  position: absolute;
  bottom: -2.5px;
  left: -3px;
  width: 32px;
  height: 3px;
  background: #8fb6a5;
  border-radius: 2px 2px 50% 50%;
}

/* 蒸汽 - 保持在杯子上方 */
.nook-steam-layer {
    position: absolute;
    top: -14px;
    left: 5px;
    width: 16px;
    height: 14px;
    display: flex;
    justify-content: space-between;
}

.steam-line {
  display: block;
  width: 2px;
  height: 10px;
  background: rgba(87, 121, 110, 0.3);
  border-radius: 4px;
  animation: steam-rise 1.8s ease-in-out infinite;
}

.steam-line:nth-child(2) {
  animation-delay: 0.5s;
  height: 8px;
}
.steam-line:nth-child(3) {
  animation-delay: 1s;
  height: 12px;
}

@keyframes steam-rise {
  0%, 100% {
    transform: translateY(0);
    opacity: 0.3;
  }
  50% {
    transform: translateY(-8px);
    opacity: 0.8;
  }
}

/* 入座按钮 */
.nook-cafe-action-btn {
  padding: 6px 14px;
  background: #57796e;
  color: #ffffff;
  border: none;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
  letter-spacing: 0.5px;
  margin-top: 4px;
}

.nook-cafe-action-btn:hover {
  background: #3a5149;
  box-shadow: 0 4px 12px rgba(87, 121, 110, 0.3);
  transform: translateY(-1px);
}

.nook-cafe-action-btn:active {
  transform: translateY(0);
}

.nook-cafe-right::after {
  display: none !important;
  content: none !important;
}

/* ---------- 滚动条 ---------- */
.nook-content::-webkit-scrollbar-thumb {
  background: #8fb6a5;
}

/* ---------- 响应式 ---------- */
@media (max-width: 480px) {
  .nook-head {
    background: linear-gradient(135deg, #eef5f1, #e3ece6);
  }
}

