data.css:
/* --- 基礎設置 --- */
body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", "Arial", sans-serif;
  font-weight: 500;
  box-sizing: border-box;
}

.widget-container {
  width: 100%;
  height: 100%;
  background: #000;
  border-radius: 22px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.icon {
  width: 22px;
  height: 22px;
  stroke: #fff;
  fill: none;
}

/* --- 頂部欄 --- */
.top-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 4px 12px;
  flex-shrink: 0;
  z-index: 10;
}
.chevron-icon {
  width: 18px; height: 18px; stroke: #888;
  background: rgba(40,40,40,0.7);
  padding: 2px; border-radius: 4px;
}
.live-icon { stroke: #f5d300; }

/* --- 相機預覽 --- */
.camera-view {
  flex-grow: 1;
  width: 100%;
  min-height: 50%;
  background-color: #333;
  background-size: cover;
  background-position: center;
}

/* --- 底部控制 --- */
.bottom-controls {
  padding: 4px 0 0 0; /* 移除底部padding，通过action-bar控制 */
  display: flex;
  flex-direction: column;
  gap: 4px; /* 缩小与模式选择的间距 */
  flex-shrink: 0;
}

.mode-selector {
  display: flex;
  justify-content: center;
  gap: 16px;
  white-space: nowrap;
  width: 100%;
  overflow: hidden;
  color: #8e8e93;
  font-size: 11px;
  position: relative;
}
.mode-selector::before, .mode-selector::after {
    content: ''; position: absolute; width: 30px;
    height: 100%; top: 0; z-index: 1;
}
.mode-selector::before { left: 0; background: linear-gradient(to right, #000, transparent); }
.mode-selector::after { right: 0; background: linear-gradient(to left, #000, transparent); }
.mode-selector span.active { color: #F5D300; }

.action-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 20px 8px 20px; /* 调整边距并增加底部空间 */
  position: relative;
}

.gallery-preview,
.switch-camera-button {
  transform: translateY(-2px); /* 【修改】向上移动10px */
}

.gallery-preview {
  width: 32px; /* 【修改】保持尺寸 */
  height: 32px;
  border-radius: 6px;
  background-color: #222;
  background-size: cover;
  background-position: center;
}

.shutter-button {
  width: 30px; /* 【修改】再次缩小 */
  height: 30px;
  background: #fff;
  border-radius: 50%;
  border: 2px solid #000;
  box-shadow: 0 0 0 1px #fff;
}

.switch-camera-button {
  width: 30px;
  height: 30px;
  background: #2c2c2e;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.switch-camera-button .icon {
  width: 18px; /* 【修改】恢复第一版图标的样式 */
  height: 18px;
}

custom.css:
.page { position: absolute; inset: 0; color: #fff; font-family: -apple-system, "PingFang SC", sans-serif; }
.bg { position: absolute; inset: 0; background: {{accent}} url("{{portrait}}") center top / cover no-repeat; }
.bg::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,.4), rgba(0,0,0,0) 30%, rgba(0,0,0,0) 55%, rgba(0,0,0,.6)); }
.clock { position: absolute; left: 24px; top: calc(var(--safe-top, 44px) + 16px); }
.clock b { display: block; font-size: 64px; line-height: 1; letter-spacing: -1px; }
.clock small { display: block; margin-top: 6px; font-size: 14px; opacity: .9; }
.card { position: absolute; left: 20px; right: 20px; bottom: 124px; padding: 12px 16px; border-radius: 16px; background: rgba(255,255,255,.92); color: #333; }
.card em { font-style: normal; font-size: 13px; font-weight: 700; color: {{accent}}; }
.card p { margin: 4px 0 0; font-size: 15px; line-height: 1.5; }
.apps { position: absolute; left: 16px; right: 16px; bottom: 44px; display: flex; gap: 10px; }
.app { flex: 1; padding: 14px 0; border-radius: 16px; text-align: center; font-size: 13px; font-weight: 700; background: rgba(0,0,0,.35); border: 1px solid rgba(255,255,255,.35); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.app.start { background: {{accent}}; border-color: transparent; }
@keyframes rise { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
@keyframes shine { 0% { background-position: 150% 0; } 60%, 100% { background-position: -50% 0; } }
html.tp-fx:not(.tp-enter) .clock, html.tp-fx:not(.tp-enter) .card, html.tp-fx:not(.tp-enter) .apps { opacity: 0; }
.tp-enter .clock { animation: rise .8s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .card { animation: rise .8s .15s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .apps { animation: rise .8s .3s cubic-bezier(.2,.8,.2,1) both; }
.app.start { background-image: linear-gradient(110deg, transparent 35%, rgba(255,255,255,.55) 50%, transparent 65%); background-size: 250% 100%; background-repeat: no-repeat; animation: shine 3s ease-in-out infinite; }

value.css:
/* ===== 窗外 ===== */
:root {
  --nook-text: #577E72 !important;
  --nook-sub: #577E72 !important;
  --nook-accent: #577E72 !important;
}

/* 覆盖所有文本类（顶部栏除外） */
.nook-reader-page,
.nook-para,
.nook-ch-title,
.nook-ch-orn,
.nook-ch-rule,
.nook-ch-end,
.nook-hl,
.nook-scribble,
.nook-hl-user,
.nook-underline-user,
.nook-wave-user,
.nook-usersel,
.nook-para-mark,
.nook-username-mark,
.nook-warn-chip,
.nook-note,
.nook-note-head,
.nook-note-ava,
.nook-note-name,
.nook-note-body,
.nook-note-reply,
.nook-buddy,
.nook-buddy-avatar,
.nook-buddy-bubble,
.nook-buddy-panel,
.nook-buddy-input,
.nook-selbar {
  color: #577E72 !important;
}

/* ===== 顶部栏 ===== */
.nook-reader-head {
  background: #729F91 !important;
  color: #ffffff !important;
  border-bottom: none !important;
  box-shadow: none !important;
}
.nook-reader-head * {
  color: #ffffff !important;
}
.nook-reader-title {
  text-shadow: none !important;
}
.nook-icon-btn,
.nook-reader-head .nook-icon-btn {
  color: #ffffff !important;
}

/* ===== 顶部工具栏（胶囊按钮） ===== */
.nook-reader-toolbar {
  border-bottom: none !important;
  box-shadow: none !important;
  background: transparent !important;
}
.nook-reader-toolbar .nook-chip {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 0 0.5em !important;
  margin: 0 !important;
  color: #51766B !important;
  font-weight: normal !important;
}
.nook-reader-toolbar .nook-chip.active {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: #51766B !important;
  font-weight: bold !important;
}

/* ===== 翻页页码（右下角 数字/数字）去除包裹 ===== */
.nook-flip-ind {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 0 !important;
  color: #577E72 !important;
}

/* ===== 翻页按钮（上一页/下一页）半透明磨砂背景 + 米白边框（通用版，已验证有效） ===== */
.nook-reader-page button:last-child,
.nook-reader-page button:first-child,
.nook-reader [class*="arrow"],
.nook-reader [class*="prev"],
.nook-reader [class*="next"] {
  background: rgba(255, 255, 255, 0.3) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
  border: 1px solid #FDF5E6 !important;
  border-radius: 4px !important;
}

/* ===== 批注按钮替换为图片（段末标记） ===== */
.nook-para-mark,
.nook-username-mark {
  display: inline-block !important;
  width: 1.2em !important;
  height: 1.2em !important;
  background-image: url('https://img.baibai.cv/f/QvGgca/1000036328.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  outline: none !important;
  padding: 0 !important;
  margin: 0 0 0 0.1em !important;
  vertical-align: middle !important;
  overflow: hidden !important;
  text-indent: -9999px !important;
  white-space: nowrap !important;
  font-size: 1em !important;
  line-height: 1 !important;
}

/* ===== 便签样式 ===== */
.nook-note {
  border: 1px solid #D8EEE7 !important;
  background: rgba(255, 255, 255, 0.7) !important;
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
  box-shadow: none !important;
  border-left: none !important;
}
.nook-note .nook-icon-btn,
.nook-note button,
.nook-note [class*="close"],
.nook-note [class*="cancel"] {
  color: #313735 !important;
}

/* ===== 便签内引用消息背景（淡绿色） ===== */
.nook-note .quote,
.nook-note blockquote,
.nook-note [class*="quote"],
.nook-note [class*="cite"] {
  background-color: #D8EEE7 !important;
}

/* ===== 便签内按键背景 #61877C ===== */
.nook-note button,
.nook-note .nook-btn,
.nook-note [class*="btn"] {
  background-color: #61877C !important;
  color: #ffffff !important;
  border: none !important;
  border-radius: 4px !important;
  padding: 4px 12px !important;
}

/* ===== 底部面板 ===== */
.nook-buddy {
  display: block !important;
  background: rgba(255, 255, 255, 0.25) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border: none !important;
  box-shadow: none !important;
  position: relative !important;
  height: 50px !important;
  padding: 0 !important;
}

.nook-buddy-panel {
  font-size: 0 !important;
  color: transparent !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  display: block !important;
  height: 100% !important;
}

/* ---- 小气泡样式 ---- */
.nook-buddy-bubble {
  display: block !important;
  font-size: 0 !important;
  background: rgba(244, 242, 232, 0.5) !important;
  backdrop-filter: blur(4px) !important;
  -webkit-backdrop-filter: blur(4px) !important;
  border-radius: 30px !important;
  padding: 8px 16px !important;
  width: 20% !important;
  min-width: 80px !important;
  position: relative !important;
  box-sizing: border-box !important;
}
.nook-buddy-bubble::before {
  content: "你說" !important;
  font-size: 1rem !important;
  color: #577E72 !important;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  white-space: nowrap;
}

.nook-buddy-avatar,
.nook-buddy-input,
.nook-buddy-name,
.nook-buddy-status {
  display: none !important;
}

.nook-buddy button,
.nook-buddy .nook-icon-btn,
.nook-buddy [class*="btn"],
.nook-buddy [class*="icon"] {
  display: inline-block !important;
  font-size: 1rem !important;
  line-height: 1 !important;
  width: 2em !important;
  height: 2em !important;
  background-image: url('https://img.baibai.cv/f/LZM5cg/1000036330.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  outline: none !important;
  padding: 0 !important;
  margin: 0 !important;
  overflow: visible !important;
  text-indent: -9999px !important;
  white-space: nowrap !important;
  position: absolute !important;
  right: 15px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  z-index: 2 !important;
}

.nook-buddy::before {
  content: "窗外是佛罗伦萨 ，桌上是死";
  font-size: 1rem !important;
  color: #577E72 !important;
  position: absolute !important;
  left: 40% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important;
  white-space: nowrap !important;
  pointer-events: none !important;
  z-index: 1 !important;
  font-weight: normal;
  line-height: normal !important;
}

@keyframes qinghuan {}

/* ---------- 主容器 ---------- */
#book-nook-screen {
  background: #f3f3f3;
  color: #ffffff;
}

/* ---------- 顶栏 ---------- */
.nook-head {
  background:#4c917c;
  border-bottom:none;
  box-shadow:none;
}

/* 返回和加号 按钮 */
.nook-head .nook-icon-btn {
  color: #ffffff;
  background: transparent;
}

.nook-head .nook-icon-btn:hover {
  color: #57796e;
}

/* 标题 "一起看" */
.nook-head .nook-head-title {
  color: #ffffff;
  text-shadow:none;
}

.nook-head .nook-head-title svg {
  color: #ffffff;
}

.nook-head .nook-head-title svg path:first-child {
  fill: #8a2121;
  stroke: none;
}

/* "我" 按钮 */
.nook-head .nook-user-wrap .nook-user-btn {
  background: rgba(87, 121, 110, 0.2);
  border: 1px solid #ffffff;
  color: #ffffff;
}

.nook-head .nook-user-wrap .nook-user-btn:hover {
  background: rgba(87, 121, 110, 0.4);
  border-color: #57796e;
  color: #57796e;
}

.nook-head .nook-user-btn svg {
  color: #ffffff;
}

.nook-head .nook-user-btn:hover svg {
  color: #57796e;
}

/* ---------- 内容区 ---------- */
.nook-content {
  background: #f3f3f3;
}

/* ---------- 过滤栏 ---------- */
/* 过滤栏容器 */
.nook-filter-bar {
  background: #ffffff;
  padding: 16px;
  border-radius: 0 0 12px 12px;
}

/* 搜索框 */
.nook-search-box {
  background: #f7f7f7;
  border: 1.5px solid #c2c2c2;
  border-radius: 30px;
}

.nook-search-box:focus-within {
  border-color: #57796e;
}

.nook-search-box .nook-search-icon {
  color: #c2c2c2;
  opacity: 1;
  stroke-width: 3;
}

.nook-search-box .nook-search-input {
  background: transparent;
  color: #505050;
}

.book-nook-screen .nook-search-box .nook-search-input::placeholder {
	color: #c2c2c2;
}

.book-nook-screen .nook-search-box .nook-search-input {
  outline: none !important;
  border-color: transparent !important;
  box-shadow: none !important;
}

.nook-search-box .nook-search-input:focus {
  outline: none !important;
  box-shadow: none !important;
}

.nook-search-box .nook-search-input:hover {
  outline: none !important;
  box-shadow: none !important;
}

/* 标签按钮 "阅读中" 和 "已完结" */
.nook-tabs .nook-tab-btn.active {
  background: #e8f0ec !important;
  color: #57796e !important;
  box-shadow: inset 0 -2px 0 #57796e !important;
  text-shadow: none !important;
}

.nook-tabs .nook-tab-btn {
  background: #f7f7f7;
  color: #888888;
  border: none;
}

.nook-tabs .nook-tab-btn:hover {
  background: #e8f0ec;
  color: #57796e;
}

.nook-tab-btn svg {
  color: currentColor;
}

/* ---------- 加载提示 ---------- */
.nook-loading {
  color: #888888;
  animation: pulse-text 1.8s ease-in-out infinite;
}

/* 整个加载容器 */
.nook-import-busy {
  color: #4c917c;
}

/* SVG 图标 */
.nook-import-busy svg {
  color: #4c917c;
}

/* 文字 */
.nook-import-busy p {
  color: #4c917c;
}

/* ========== 导入弹窗 ========== */

/* 弹窗遮罩  */
.nook-modal-overlay {
  background: rgba(0, 0, 0, 0.3);
}

/* 加号弹出菜单 */
.nook-add-menu,
.nook-user-menu {
  background: #ffffff;
  border: none;
  border-radius: 12px;
  box-shadow: 0 10px 20px #505050;
}

.nook-add-menu button,
.nook-user-menu button {
  color: #505050;
  background: transparent;
  transition: background 0.2s, color 0.2s;
}

.nook-add-menu button:hover,
.nook-user-menu button:hover {
  background: #e8f0ec;
  color: #4c917c;
}

.nook-add-menu button svg,
.nook-user-menu button svg {
  color: #4c917c;
}

/* 弹窗主体 */
.nook-modal {
  background: #ffffff;
  border-radius: 20px;
  border: none;
  outline: none !important;
  box-shadow: 0 10px 20px #505050;
}

/* 弹窗头部 */
.nook-modal-head {
  border-bottom: 1px solid #4c917c;
}

.book-nook-screen .nook-modal-head svg {
  color: #4c917c;
}

.nook-modal-title {
  color: #4c917c;
}

/* 导入选项容器 */
.nook-import-choices {
  background: #ffffff;
  box-shadow: none;
}

/* 单个导入选项 */
.nook-import-choice {
  background: #f3f3f3;
  border: 1px solid #c2c2c2;
  border-radius: 14px;
  transition: background 0.2s, border-color 0.2s, box-shadow 0.2s;
  box-shadow: none;
}

.nook-import-choice:hover {
  background: #e8f0ec;
  border: none;
}

.nook-import-choice svg {
  color: #4c917c;
}

.nook-import-choice-title {
  color: #505050;
}

.nook-import-choice-sub {
  color: #c2c2c2;
}

/* 回忆录用户行 */
.nook-user-chip {
  color: #505050;
  background: #f3f3f3;
  border: 1px solid #c2c2c2;
  border-radius: 12px;
  transition: all 0.25s ease;
  outline: none;
}

/* 点击状态 */
.nook-user-chip:active {
  background: #e8f0ec;
  border-color: #57796e;
  transform: scale(0.96);
}

/* 选中/激活状态 */
.nook-user-chip.active {
  background: #e8f0ec;
  border-color: #4c917c;
  color: #505050;
}

/* 回忆录行 */
.nook-memoir-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: #ffffff;
  border-radius: 12px;
  border: 1px solid #e8f0ec;
  margin-bottom: 8px;
  transition: all 0.3s ease;
}

.nook-memoir-row:hover {
  border-color: #57796e;
}

.nook-memoir-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.nook-memoir-title {
  font-size: 16px;
  font-weight: 600;
  color: #264a3f;
}

.nook-memoir-sub {
  font-size: 12px;
  color: #57796e;
}

.nook-memoir-acts {
  display: flex;
  gap: 10px;
}

.nook-memoir-acts button {
  padding: 6px 18px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 500;
  border: none;
  cursor: pointer;
  transition: all 0.3s ease;
}

.nook-memoir-gen {
  background: #57796e;
  color: #ffffff;
}

.nook-memoir-gen:hover {
  background: #264a3f;
  transform: translateY(-1px);
}

.nook-memoir-gen:active {
  transform: translateY(0);
}

.nook-memoir-sync {
  background: #e8f0ec;
  color: #57796e;
  font-weight: bold;
}

.nook-memoir-sync:hover:not(:disabled) {
  background: #8fb6a5;
  transform: translateY(-1px);
}

.nook-memoir-sync:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none !important;
  box-shadow: none !important;
}

/* ---------- 回忆小说弹窗主体（玻璃效果） ---------- */
.hl-modal.glass.hl-novel-reader {
  background: #ffffff;
  border-radius: 20px;
  display: flex;
  flex-direction: column;
  max-height: 90vh;
  overflow: hidden;
}

.hl-modal {
  border: none;
}

/* 弹窗头部 */
.hl-modal-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  border-bottom: 1px solid #4c917c;
  flex-shrink: 0;
}

/* 标题文字 */
.hl-modal-title {
  flex: 1;
  font-size: 18px;
  font-weight: 600;
  color: #4c917c;
  text-align: start;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* 头部按钮通用 */
.hl-modal-back,
.hl-modal-close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: none;
  background: transparent;
  color: #4c917c;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.hl-modal-back:hover,
.hl-modal-close:hover {
  background: transparent;
  color: #57796e;
}

/* 内容区（空白状态） */
.hl-novel-toc {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
}

.hl-showcase-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 20px;
  text-align: center;
}

.hl-showcase-empty svg {
  color: #4c917c;
  opacity: 0.6;
}

.hl-showcase-empty p {
  color: #c2c2c2;
  font-size: 14px;
  line-height: 1.6;
  max-width: 280px;
  margin: 0;
}

/* 底部操作区 */
.hl-novel-foot {
  border-top: 1px solid #c2c2c2;
  border-radius: 12px 12px 0 0;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  flex-shrink: 0;
  background: #ffffff;
}

/* 文风设定面板 */
.hl-novel-style {
  display: flex;
  flex-direction: column;
  gap: 10px;
  border: 1px solid #c2c2c2;
}

/* 小标题 */
.hl-novel-style-label {
  font-size: 13px;
  font-weight: 600;
  color: #4c917c;
  opacity: 1;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* 选项标签组 */
.hl-novel-style-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

/* 单个选项标签 */
.hl-novel-chip {
  padding: 6px 14px;
  font-size: 13px;
  font-weight: 500;
  color: #505050;
  background: #ffffff;
  border: 1px solid rgba(76,145,124,0.5);
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;
  white-space: nowrap;
}

.hl-novel-chip:hover {
  background: #e8f0ec;
  border-color: #4c917c;
  color: #505050;
}

/* 文风选项选中态 */
.hl-novel-chip.active,
.hl-novel-style-chips .hl-novel-chip.selected {
  background: #e8f0ec;
  border-color: #4c917c;
  color: #264a3f;
}

/* 自定义文风输入框 */
.hl-novel-style-input {
  padding: 10px 14px;
  font-size: 13px;
  color: #505050;
  background: #f3f3f3;
  border: 1px solid rgba(76,145,124,0.5);
  border-radius: 10px;
  resize: vertical;
  font-family: inherit;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.hl-novel-style-input::placeholder {
  color: #c2c2c2;
}

.hl-novel-style-input:focus {
  border-color: #4c917c;
}

.book-nook-screen .hl-novel-foot .hl-novel-style .hl-novel-style-save-row .hl-novel-style-name:focus {
  border-color: rgba(76, 145, 124, 0.5) !important;
}

/* 整体行容器 */
.hl-novel-style-save-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: none;
}

/* 输入框 */
.hl-novel-style-name,
.hl-novel-style-name:focus,
.hl-novel-style-name:focus-visible,
.hl-novel-style-name:active {
  flex: 1;
  font-size: 13px;
  color: #505050;
  background: #f3f3f3;
  border: 1px solid rgba(76,145,124,0.5);
  border-radius: 10px;
  outline: none !important;
  outline-style: none !important;
  box-shadow: none !important;
  font-family: inherit;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.book-nook-screen .hl-novel-foot .hl-novel-style .hl-novel-style-input:focus {
  border-color: rgba(76, 145, 124, 0.5) !important;
}

.hl-novel-style-name::placeholder {
  color: #505050;
  font-size: 13px;
}

.hl-novel-style-name:focus {
  border: 1px solid rgba(76,145,124,0.5);
  box-shadow: none !important;
}

/* 收藏按钮 */
.hl-novel-chip.save {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 500;
  color: #4c917c;
  background: #e8f0ec !important;
  border: 1px solid rgba(76,145,124,0.5);
  border-radius: 10px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
  outline: none;
}

.hl-novel-chip.save:hover {
  background: #8fb6a5;
  border-color: #4c917c;
  transform: translateY(-1px);
}

.hl-novel-chip.save:active {
  transform: translateY(0);
  background: #8fb6a5;
}

/* 通用按钮 */
.hl-novel-style .hl-novel-btn {
	display: flex !important;
	width: 100% !important;
	box-sizing: border-box !important;
}

.hl-novel-btn {  
  padding: 10px 20px;
  font-size: 12px;
  font-weight: 800;
  color: #ffffff;
  background: #57796e;
  border: 1px solid #57796e;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.25s ease;
  outline: none;
  display: inline-flex;
  align-items: center;
  align-self: center;
  justify-content: center;
  gap: 6px;
}

.book-nook-screen .hl-novel-btn svg {
  flex-shrink: 0;
  display: inline-block;
  vertical-align: middle;
  color: #ffffff !important;
  stroke: #ffffff !important;
}

.hl-novel-btn.primary {
	display: flex !important;
	width: 100% !important;
	box-sizing: border-box !important;
}

.hl-novel-free-hint {
	color:#c2c2c2 !important;
}

/* 开关按钮整体 */
.hl-novel-toggle {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
  background: #ffffff;
  border: 1px solid rgba(76,145,124,0.5);
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.25s ease;
  outline: none;
  width: 100%;
  text-align: left;
  color: #505050;
}

.hl-novel-toggle.on {
  background: rgba(76,145,124,0.3);
  border: 1px solid #4c917c;
}

/* 开关圆点 */
.hl-novel-toggle-dot {
  flex: none;
  width: 34px;
  height: 20px;
  border-radius: 20px;
  background: rgba(76,145,124,0.2);
  position: relative;
  transition: all 0.25s ease;
  margin-top: 2px;
}

.hl-novel-toggle-dot.on {
  background: rgba(76,145,124,0.8);
}

/* 标题 */
.hl-novel-toggle-title {
  font-size: 13px;
  font-weight: 600;
  color: #264a3f;
  line-height: 1.4;
}

/* 描述 */
.hl-novel-toggle-desc {
  font-size: 11px;
  color: #505050;
  line-height: 1.4;
}

/* ========== 日期范围选择行 ========== */
/* 日期输入框 */
.hl-novel-date,
.hl-novel-date:focus,
.hl-novel-date:focus-visible {
  font-size: 13px;
  color: #505050;
  background: #f3f3f3;
  border: 1px solid rgba(76, 145, 124, 0.5) !important;
  border-radius: 10px;
  outline: none !important;
  box-shadow: none !important;
  font-family: inherit;
  transition: border-color 0.2s;
}

/* 箭头分隔符 */
.hl-novel-range-sep {
  opacity: 1;
  color: #2b2b2b;
}

.hl-novel-ch-title {
	color: #264a3f;
}

.hl-novel-fontbar button {
    border: 1px solid rgba(76, 145, 124, 0.5);
    background: #e8f0ec;
    color: #4c917c;
    border-radius: 8px;
    padding: 2px 8px;
    font-size: 12px;
    cursor: pointer;
}

.hl-novel-toc-item {
    display: flex;
    align-items: baseline;
    gap: 10px;
    padding: 10px 12px;
    border-radius: 12px;
    border: 1px solid rgba(76, 145, 124, 0.5);
    background: #f3f3f3;
    cursor: pointer;
    text-align: left;
}

.hl-novel-toc-num {
    font-size: 12px;
	color: #4c917c;
    opacity: .8;
}

.hl-novel-toc-title {
    font-size: 14px;
    font-weight: 600;
	color: #264a3f;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* ========== 皮肤保存行 ========== */
/* 整体行容器 */
.nook-skin-saverow {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
}

/* 输入框 */
.nook-skin-saverow input {
  flex: 1;
  padding: 8px 14px;
  font-size: 13px;
  color: #505050;
  background: #f3f3f3;
  border: 1px solid rgba(76, 145, 124, 0.5);
  border-radius: 10px;
  outline: none !important;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.nook-skin-saverow input::placeholder {
  color: #c2c2c2;
}

.nook-skin-saverow :focus {
  border-color: none !important;
}

/* 保存按钮 */
.nook-skin-saverow .nook-pick-start {
  margin: 0 !important;
  width: auto !important;
  padding: 8px 20px !important;
  font-size: 14px;
  font-weight: 500;
  text-shadow: none;
  background: #57796e;
  border: 1px solid #57796e;
  border-radius: 10px;
  color: #ffffff;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.25s ease;
  box-shadow: none;
}

.nook-skin-saverow .nook-pick-start:hover {
  background: #264a3f;
  border-color: #264a3f;
  transform: translateY(-1px);
  box-shadow: none;
}

.nook-skin-saverow .nook-pick-start:active {
  transform: translateY(0);
  background: #3a5149;
}

/* 弹窗提示文字 */
.nook-pick-hint {
  color: #505050;
  text-shadow: none;
}

/* CSS 输入框 */
.nook-beautify-css {
  width: calc(100% - 20px) !important;
  box-sizing: border-box !important;
  background: #f3f3f3;
  border: 1px solid rgba(76, 145, 124, 0.5);
  padding: 10px;
  margin: 10px;
  color: #505050;
}

.nook-beautify-css:focus {
  border-color: 1px solid rgba(76, 145, 124, 0.5);
  box-shadow: none;
}

/* 去除所有状态下的 outline 和 box-shadow */
textarea.nook-set-css.nook-beautify-css,
textarea.nook-set-css.nook-beautify-css:focus,
textarea.nook-set-css.nook-beautify-css:hover,
textarea.nook-set-css.nook-beautify-css:active,
textarea.nook-set-css.nook-beautify-css:focus-visible,
textarea.nook-set-css.nook-beautify-css:focus-within,
.nook-skin-saverow input:focus,
.nook-skin-saverow input:focus-visible,
.nook-skin-saverow input:active {
  outline: none !important;
  outline-style: none !important;
  box-shadow: none !important;
  border: 1px solid rgba(76, 145, 124, 0.5) !important;
}

/* 底部操作按钮 */
.nook-beautify-actions {
  margin: 10px;
}

.nook-beautify-actions .nook-set-bg-clear {
  background: #57796e;
  border: 1px solid #57796e;
  color: #ffffff;
  padding: 3px 10px;
}

.nook-beautify-actions .nook-set-bg-clear:hover {
  background: #264a3f;
  color: #ffffff;
}

.nook-beautify-actions .nook-pick-start {
  background: #264a3f;
  border: 1px solid #264a3f;
  box-shadow: none;
  color: #ffffff;
  padding: 3px 10px !important;
}

.nook-beautify-actions .nook-pick-start:hover {
  background: #57796e;
}

/* ========== 皮肤行 ========== */
/* 整行 */
.nook-skin-row {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 14px;
}

/* "我的皮肤" 标签 */
.nook-skin-label {
  font-size: 13px;
  font-weight: 700;
  color: #000000;
  flex-shrink: 0;
}

/* 皮肤标签容器 */
.nook-skin-chip {
  display: inline-flex;
  align-items: center;
  background: #e8f0ec;
  border: 1px solid rgba(76, 145, 124, 0.5);
}

/* 皮肤名称按钮 */
.nook-skin-load {
  font-size: 12px;
  font-weight: 500;
  color: #4c917c;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 5px 5px 5px 12px;
  outline: none;
}

.nook-skin-load:hover {
  color: #4c917c;
}

/* 删除按钮 */
.nook-skin-del {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  padding: 0;
  background: transparent;
  border: none;
  border-radius: 50%;
  cursor: pointer;
  color: #888888;
  transition: all 0.2s ease;
  outline: none;
}

.nook-skin-del:hover {
  color: #8a2121;
}

.nook-skin-del svg {
  width: 12px;
  height: 12px;
}

/* ---------- 书卡 (预留) ---------- */
.nook-book-cover {
  border: none !important;
  outline: none !important;
  box-shadow: 0 4px 16px rgba(87, 121, 110, 0.2) !important;
  overflow: hidden !important;
}

.nook-parchment-cover {
  box-shadow: inset 0 0 25px rgba(87, 121, 110, 0.2) !important;
}

.nook-parchment-gold-stamp {
  position: absolute;
  top: 5px;
  right: 5px;
  bottom: 5px;
  left: 5px;
  border: 1px solid rgba(87, 121, 110, 0.5);
  border-radius: 5%;
  pointer-events: none;
  z-index: 1;
}

*, *:before, *:after {
  box-shadow: none !important;
  --tw-ring-offset-shadow: none !important;
  --tw-ring-shadow: none !important;
  --tw-ring-color: transparent !important;
}

.nook-parchment-rococo-border {
	border-radius: 5%;
}

.nook-parchment-rococo-border::before,
.nook-parchment-rococo-border::after {
  display: none !important;
  content: none !important;
}

/* 封面背景 - 白到浅绿渐变 */
.nook-parchment-cover {
  background: linear-gradient(135deg, #ffffff, #e8f0ec) !important;
}

/* 标签 NOVEL */
.nook-parchment-label {
  color: #57796e !important;
  background: transparent !important;
}

/* 主标题 */
.nook-parchment-title {
  color: #264a3f !important;
}

/* 副标题 */
.nook-parchment-title-sub {
  color: #57796e !important;
}

/* 作者 */
.nook-parchment-author {
  color: #8fb6a5 !important;
}

/* 金色装饰边框改成绿色调 */
.nook-parchment-rococo-border {
  border-color: #8fb6a5 !important;
}

/* 进度条背景 - 浅绿/白色 */
.nook-book-progress-bar {
  background: rgba(232, 240, 236, 0.8) !important;
}

/* 进度条填充 - 墨绿色 */
.nook-book-progress-fill {
  background: #57796e !important;
}

/* 木底座 - 改成白绿 */
.nook-wood-plinth {
  width: 96px;
  height: 7px;
  background: linear-gradient(180deg, #e8f0ec, #8fb6a5);
  border-bottom: 2px solid #57796e;
  border-radius: 3px;
  box-shadow: 0 2px 6px rgba(87, 121, 110, 0.15), inset 0 1px rgba(255, 255, 255, 0.3);
  margin-top: -3px;
  position: relative;
  z-index: 4;
}

.nook-wood-plinth::before {
  background: linear-gradient(180deg, rgba(0, 0, 0, 0.1), transparent) !important;
  box-shadow: none !important;
}

/* 书名 - 改成白绿 */
.nook-book-title {
  font-size: 11.5px;
  font-weight: 700;
  color: #264a3f;
  text-shadow: none;
  text-align: center;
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-top: 4px;
  width: 100%;
  max-width: 90px;
}

/* 时长标签 - 改成白绿 + 加框 */
.nook-book-duration-badge {
  font-size: 8.5px;
  font-weight: 700;
  color: #57796e;
  opacity: 0.85;
  margin-top: 1px;
  text-align: center;
  padding: 2px 12px;
  border: 1px solid rgba(87, 121, 110, 0.3);
  border-radius: 12px;
  background: rgba(232, 240, 236, 0.4);
  display: inline-block;
}

/* 整个面板 */
.nook-sheet {
  background: #ffffff;
  border-radius: 16px;
  padding: 20px 0;
  box-shadow: 0 8px 32px rgba(87, 121, 110, 0.15);
  border: 1px solid #e8f0ec;
  min-width: 220px;
}

.nook-book-badge {
    position: absolute;
    top: 7px;
    right: -15px;
    font-size: 8px;
    font-weight: 800;
    padding: 1px 13px;
    color: #ffffff;
    transform: rotate(45deg);
    z-index: 6;
    box-shadow: 0 1px 4px #0006;
    letter-spacing: .5px;
    transform-origin: center;
    scale: .85;
}

/* 标题 */
.nook-sheet-title {
  font-size: 16px;
  font-weight: 800;
  color: #264a3f;
  padding: 0 20px 12px 20px;
  border-bottom: 1px solid #e8f0ec;
  margin-bottom: 8px;
}

/* 菜单项 */
.nook-sheet-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 20px;
  background: transparent;
  border: none;
  font-size: 14px;
  color: #264a3f;
  cursor: pointer;
  transition: background 0.2s ease;
  text-align: left;
}

.nook-sheet-item:hover {
  background: #e8f0ec;
}

.nook-sheet-item svg {
  color: #264a3f;
  stroke: #264a3f;
  flex-shrink: 0;
}

/* 危险项（删除） */
.nook-sheet-item.danger {
  color: #8a2121;
}

.nook-sheet-item.danger svg {
  color: #8a2121;
  stroke: #8a2121;
}

.nook-sheet-item.danger:hover {
  background: #e8f0ec;
}

/* 取消按钮 */
.nook-sheet-cancel {
  display: block;
  width: calc(100% - 40px);
  margin: 8px 20px 0 20px;
  padding: 10px 0;
  background: #e8f0ec;
  border: none;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  color: #264a3f;
  cursor: pointer;
  transition: background 0.2s ease;
}

.nook-sheet-cancel:hover {
  background: #8fb6a5;
}

/* 网格容器 */
.book-nook-screen .nook-modal {
  background: #ffffff;
  border-radius: 20px;
  border: none;
  outline: none !important;
  box-shadow: 0 10px 20px #505050;
  overflow-y: visible !important;
  max-height: none !important;
  height: auto !important;
}

.nook-partner-grid {
  width: 100%;
  box-sizing: border-box;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  padding: 16px;
  overflow-y: auto;
}

/* 单个伙伴卡片 - 改成白绿 */
.nook-partner {
  width: 100%;
  min-width: 0;
  min-height: 118px;
  box-sizing: border-box;
  overflow: hidden;
  background: #ffffff;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  color: #264a3f;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 14px 8px 12px;
  transition: all 0.2s ease;
  box-shadow: 0 2px 8px rgba(87, 121, 110, 0.06);
}

.nook-partner:hover {
  background: #e8f0ec;
  border-color: #8fb6a5;
  box-shadow: none;
  transform: translateY(-2px);
}

.nook-partner:active {
  transform: translateY(0);
}

/* 头像容器 */
.nook-partner-avatar-container {
  position: relative;
  display: inline-flex;
  margin-bottom: 2px;
}

/* 头像 - 加个背景和边框 */
.nook-partner-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: #e8f0ec;
  border: none;
}

.nook-partner-avatar svg {
  color: #57796e;
  stroke: #57796e;
  width: 22px;
  height: 22px;
}

/* 名字 */
.nook-partner-name {
  font-size: 12px;
  font-weight: 700;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #264a3f;
}

/* 偏好标签 */
.nook-partner-preference {
  font-size: 8.5px;
  color: #57796e;
  transform: scale(0.85);
  margin-top: 1px;
  text-align: center;
  white-space: nowrap;
  opacity: 0.8;
  background: #e8f0ec;
  padding: 1px 8px;
  border-radius: 10px;
  border: 1px solid #8fb6a5;
}

/* 已选中的伙伴卡片 */
.nook-partner.picked {
  background: #e8f0ec !important;
  border: 2px solid #57796e !important;
  box-shadow:none;
}

.nook-partner.picked .nook-partner-avatar {
  background: #57796e !important;
  border-color: #264a3f !important;
}

.nook-partner.picked .nook-partner-avatar svg {
  color: #ffffff !important;
  stroke: #ffffff !important;
}

/* 选中标记数字 */
.nook-partner.picked .nook-partner-check {
  background: #57796e !important;
  color: #ffffff !important;
  border: 2px solid #ffffff !important;
}

/* 脉冲动画圈 */
.nook-partner.picked .nook-partner-pulse {
  border-color: #57796e !important;
}

.nook-partner.picked .nook-partner-name {
  color: #264a3f !important;
}

.nook-partner.picked .nook-partner-preference {
  color: #57796e !important;
  background: rgba(255, 255, 255, 0.5) !important;
  border-color: #8fb6a5 !important;
}

/* 整行容器 */
.nook-cat-newrow {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  margin:10px;
  background: #ffffff;
  border-radius: 10px;
  border: none;
  box-shadow: none;
}

/* 输入框 */
.nook-cat-newrow input {
  flex: 1;
  padding: 8px 14px;
  border: 1px solid #4c917c;
  border-radius: 8px;
  font-size: 14px;
  color: #000000;
  background: #e8f0ec;
  outline: none !important;
  box-shadow: none !important;
  transition: border-color 0.2s ease;
}

.nook-cat-newrow input,
.nook-cat-newrow input:focus,
.nook-cat-newrow input:hover,
.nook-cat-newrow input:active,
.nook-cat-newrow input:focus-visible {
  outline: none !important;
  outline-style: none !important;
  box-shadow: none !important;
  border-color: #4c917c;
}

.nook-cat-modal .nook-cat-newrow input:focus {
  border-color: #4c917c !important;
}

.nook-cat-newrow input::placeholder {
  color: #57796e;
}

.nook-cat-newrow input:focus-visible {
  outline: none !important;
  box-shadow: none !important;
}

/* 新建按钮 */
.nook-pick-start {
  padding: 8px 20px;
  border: none;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  text-shadow: none;
  background: #57796e;
  color: #ffffff;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.nook-pick-start:hover:not(:disabled) {
  background: #264a3f;
  box-shadow: none;
  transform: translateY(-1px);
}

.nook-pick-start:active:not(:disabled) {
  transform: translateY(0);
}

/* 禁用状态 */
.nook-pick-start:disabled {
  background: #e8f0ec;
  color: #57796e;
  text-shadow:none;
  cursor: not-allowed;
  transform: none !important;
  box-shadow: none !important;
}

.nook-cat-modal .nook-cat-pick-list {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin: 4px 14px 14px;
}

/* ========== 分类标签组 ========== */

/* 容器 */
.nook-cat-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 0;
}

/* 单个标签 */
.nook-cat-chip {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 4px;
  padding: 0 12px;
  font-size: 12px;
  font-weight: 500;
  color: rgba(136, 136, 136, 0.5);
  background: #f3f3f3;
  border: 1px solid rgba(194, 194, 194, 0.5);
  border-radius: 13px;
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;
  white-space: nowrap;
}

.nook-cat-chip svg {
  color: rgba(136, 136, 136, 0.5);
  flex-shrink: 0;
}

.nook-cat-chip:hover {
  background: #f3f3f3;
  border-color: #888888;
}

/* 选中态 */
.nook-cat-chip.active {
  background: #f7f7f7;
  border-color: #888888;
  color: #505050;
  font-weight: 600;
}

.nook-cat-chip.active svg {
  color: #505050;
}

.book-nook-screen .nook-cat-modal .nook-cat-pick-list {
	margin: 10px 14px 0 !important;
}

.nook-cat-modal .nook-sheet-item.danger {
  display: flex;
  align-items: center;
  justify-content: center;
  width: calc(100% - 40px);
  margin: 8px 20px;
  padding: 10px 0;
  background: transparent;
  border: none;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 500;
  color: #ffffff;
  background-color: #712424;
  cursor: pointer;
  transition: all 0.2s ease;
}

.nook-cat-modal .nook-sheet-item.danger svg {
  color: #ffffff;
  stroke: #ffffff;
}

.nook-cat-modal .nook-sheet-item.danger:hover {
  background: #ffffff;
  border: 1px solid #712424;
  color: #712424;
  font-weight: bold;
}

.nook-cat-modal .nook-sheet-item.danger:hover svg {
  color: #712424;
  stroke: #712424;
}

.book-nook-screen .nook-finished-seal {
  position: absolute;
  top: 5px;
  right: -17px;
  font-size: 8px;
  font-weight: 800;
  padding: 1px 13px;
  color: #ffffff;
  width: 60px;
  height: 13px;
  border-radius: 0%;
  background: linear-gradient(135deg, sienna, #5c2e16);
  transform: rotate(45deg);
  z-index: 6;
  box-shadow: none;
  letter-spacing: .5px;
  transform-origin: center;
  scale: .85;
}

.nook-finished-seal span{
    font-size: 10px;
    font-weight: 700;
    color: #ffffff;
    letter-spacing: .5px;
    transform: scale(.85);
    white-space: nowrap;
	vertical-align: middle;
}


/* ---------- 续读吧台 - 白绿 ---------- */
.nook-cafe-bar {
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  gap: 14px;
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  margin: 0;
  padding: 16px 16px calc(var(--nuo-safe-bottom, 0px) + 14px);
  border-radius: 16px 16px 0 0;
  cursor: pointer;
  background: linear-gradient(180deg, #e8f0ec, #8fb6a5);
  border: 1.5px solid rgba(87, 121, 110, 0.3);
  border-bottom: none;
  box-shadow: 0 -12px 35px rgba(87, 121, 110, 0.15), inset 0 1px rgba(255, 255, 255, 0.5);
  z-index: 1000;
  box-sizing: border-box;
  width: 100%;
}

/* 删除 .nook-cafe-bar 的伪元素 */
.nook-cafe-bar::before,
.nook-cafe-bar::after {
  display: none !important;
  content: none !important;
}

/* 删除 .nook-cafe-left 的伪元素 */
.nook-cafe-left::before,
.nook-cafe-left::after {
  display: none !important;
  content: none !important;
}

/* 左侧区域 */
.nook-cafe-left {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  flex-shrink: 0;
  width: 60px;
  position: relative;
}

.nook-cafe-avatar-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #e8f0ec;
  border: 2px solid #57796e;
}

.nook-cafe-avatar-wrap svg {
  color: #57796e;
  stroke: #57796e;
  width: 20px;
  height: 20px;
}

.nook-cafe-seat-label {
  font-size: 8.5px;
  font-weight: 800;
  color: #57796e !important;
  background: rgba(87, 121, 110, 0.3) !important;
  padding: 1px 6px;
  border-radius: 999px;
  letter-spacing: 0.5px;
}

/* 中间备忘录 - 白绿 */
.nook-napkin-memo {
  flex: 1;
  min-width: 0;
  background: #f3f3f3;
  border-radius: 6px;
  padding: 11px 12px;
  box-shadow: 4px 8px 22px rgba(87, 121, 110, 0.15), inset 0 0 10px rgba(87, 121, 110, 0.06);
  position: relative;
  transform: rotate(-1.5deg);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 4px;
  border-left: 2px dashed rgba(87, 121, 110, 0.3);
}

.nook-napkin-quote {
  font-size: 12px;
  color: #264a3f;
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  opacity: 0.85;
}

.nook-napkin-info {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.nook-napkin-char {
  font-size: 11px;
  font-weight: 600;
  color: #57796e;
}

.nook-napkin-book {
  font-size: 10px;
  color: #8fb6a5;
}

/* 右侧容器 - 确保相对定位 */
.nook-cafe-right {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
  width: 54px;
  position: relative;
}

/* 茶杯容器 - 固定尺寸和位置 */
.nook-steaming-cup {
  position: relative;
  width: 26px;
  height: 19px;
  margin-top:22px;
}

/* 杯体 */
.nook-cup-body {
  width: 100%;
  height: 100%;
  background: #57796e;
  border-radius: 1px 1px 9px 9px;
  border-top: 2px solid #8fb6a5;
  box-shadow: inset -1px -1px 3px #57796e;
  z-index:1;
}

/* 杯柄 */
.nook-cup-handle {
  position: absolute;
  top:7px;
  right: -5px;
  transform: translateY(-50%);
  width: 7px;
  height: 11px;
  border: 2px solid #57796e;
  border-left: none;
  border-radius: 0 45% 45% 0;
}

/* 杯碟 */
.nook-cup-saucer {
  position: absolute;
  bottom: -2.5px;
  left: -3px;
  width: 32px;
  height: 3px;
  background: #8fb6a5;
  border-radius: 2px 2px 50% 50%;
}

/* 蒸汽 - 保持在杯子上方 */
.nook-steam-layer {
    position: absolute;
    top: -14px;
    left: 5px;
    width: 16px;
    height: 14px;
    display: flex;
    justify-content: space-between;
}

.steam-line {
  display: block;
  width: 2px;
  height: 10px;
  background: rgba(87, 121, 110, 0.3);
  border-radius: 4px;
  animation: steam-rise 1.8s ease-in-out infinite;
}

.steam-line:nth-child(2) {
  animation-delay: 0.5s;
  height: 8px;
}
.steam-line:nth-child(3) {
  animation-delay: 1s;
  height: 12px;
}

@keyframes steam-rise {
  0%, 100% {
    transform: translateY(0);
    opacity: 0.3;
  }
  50% {
    transform: translateY(-8px);
    opacity: 0.8;
  }
}

/* 入座按钮 */
.nook-cafe-action-btn {
  padding: 6px 14px;
  background: #57796e;
  color: #ffffff;
  border: none;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
  letter-spacing: 0.5px;
  margin-top: 4px;
}

.nook-cafe-action-btn:hover {
  background: #3a5149;
  box-shadow: 0 4px 12px rgba(87, 121, 110, 0.3);
  transform: translateY(-1px);
}

.nook-cafe-action-btn:active {
  transform: translateY(0);
}

.nook-cafe-right::after {
  display: none !important;
  content: none !important;
}

/* ---------- 滚动条 ---------- */
.nook-content::-webkit-scrollbar-thumb {
  background: #8fb6a5;
}

/* ---------- 响应式 ---------- */
@media (max-width: 480px) {
  .nook-head {
    background: linear-gradient(135deg, #eef5f1, #e3ece6);
  }
}

/*----------- 空书架 -----------*/
p {
  color: #57796e;
}

.lucide-book-text {
  color: #57796e;
}

/* ================================================
   月光，夜间
   ================================================ */


/* ===== 顶部导航栏（便利贴风格） ===== */
.tm-header {
  background: rgba(255, 255, 255, 0.08) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  border-radius: 20px 4px 20px 4px !important;
  transform: rotate(-1.2deg) !important;
  box-shadow: 4px 6px 30px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.06) !important;
  margin: 12px 16px 0 16px !important;
  width: calc(100% - 32px) !important;
  padding: 12px 16px !important;
  min-height: 70px !important;
  position: relative !important;
}

/* 胶带装饰（顶部） */
.tm-header::before {
  content: '' !important;
  position: absolute !important;
  top: -10px !important;
  left: 50% !important;
  transform: translateX(-50%) rotate(-3deg) !important;
  width: 60px !important;
  height: 16px !important;
  background: rgba(255, 255, 255, 0.12) !important;
  border-radius: 20px !important;
  filter: blur(1px) !important;
  pointer-events: none !important;
}

.tm-header::after {
  content: '' !important;
  position: absolute !important;
  top: -5px !important;
  right: 15% !important;
  transform: rotate(12deg) !important;
  width: 40px !important;
  height: 12px !important;
  background: rgba(255, 255, 255, 0.08) !important;
  border-radius: 20px !important;
  filter: blur(1px) !important;
  pointer-events: none !important;
}

/* 返回按钮（隐藏但可点击） */
.tm-header .tm-btn-icon:first-child {
  opacity: 0 !important;
  pointer-events: auto !important;
}

.tm-header .tm-btn-icon:first-child svg {
  color: transparent !important;
}

/* 角色名 ———— 暖白 */
.tm-header-name {
  color: #f0ece8 !important;
  font-size: 15px !important;
  font-weight: 600 !important;
  font-style: italic !important;
  letter-spacing: 2px !important;
  text-shadow: 0 0 20px rgba(255, 255, 255, 0.06) !important;
  margin-top: 15px !important;
}

/* 分隔符 × 换成 (・ω・) */
.tm-top-vs {
  font-size: 0 !important;
  margin-top: 15px !important;
}

.tm-top-vs::before {
  content: '(・ω・)' !important;
  font-size: 15px !important;
  color: rgba(250, 250, 250, 0.5) !important;
}

/* 右侧图标按钮（电话/视频隐藏但可点击） */
.tm-header-right .tm-btn-icon {
  opacity: 0 !important;
  pointer-events: auto !important;
}

.tm-header-right .tm-btn-icon svg {
  color: transparent !important;
}

/* 顶栏头像 —— 隐藏！ */
.tm-header-avatar-wrap {
  display: none !important;
}

/* ===== 角色消息卡片（云朵气泡） ===== */
.tm-para-char {
  background: rgba(255, 255, 255, 0.08) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  border-radius: 50px 50px 50px 8px !important;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.4), 0 8px 40px rgba(0, 0, 0, 0.12) !important;
  padding: 14px 22px !important;
  position: relative !important;
}

/* 云朵尾巴（右下） */
.tm-para-char::after {
  content: '' !important;
  position: absolute !important;
  bottom: 0 !important;
  right: -10px !important;
  width: 18px !important;
  height: 18px !important;
  background: rgba(255, 255, 255, 0.08) !important;
  border-radius: 50% 50% 50% 4px !important;
  transform: rotate(-12deg) !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  border-left: none !important;
  border-bottom: none !important;
}

/* 角色文字 ———— 暖白带棕 */
.tm-body-char {
  color: #e8ddd0 !important;
  font-size: 15px !important;
  line-height: 1.8 !important;
  font-weight: 350 !important;
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.3) !important;
  transform: rotate(var(--text-rot, 0deg)) !important;
  transition: transform 0.2s ease !important;
  display: block !important;
}

/* 角色文字悬停扶正 */
.tm-body-char:hover {
  transform: rotate(0deg) !important;
}

/* 每条消息不同旋转 */
.tm-para-char:nth-child(1) .tm-body-char { --text-rot: 0.3deg; }
.tm-para-char:nth-child(2) .tm-body-char { --text-rot: -0.5deg; }
.tm-para-char:nth-child(3) .tm-body-char { --text-rot: 0.8deg; }
.tm-para-char:nth-child(4) .tm-body-char { --text-rot: -0.2deg; }
.tm-para-char:nth-child(5) .tm-body-char { --text-rot: 0.6deg; }

/* 角色Header骨架（头像+名字区域） */
.tc-meta-title {
  color: #e8ddd0 !important;
  font-size: 15px !important;
  font-weight: 600 !important;
  font-style: italic !important;
  letter-spacing: 1.5px !important;
  background: rgba(180, 150, 120, 0.04) !important;
  padding: 2px 12px !important;
  border-radius: 3px !important;
  display: inline-block !important;
  transform: rotate(-0.5deg) !important;
}

.tc-meta-subtitle {
  color: rgba(200, 180, 160, 0.2) !important;
  font-size: 10px !important;
  font-style: italic !important;
  letter-spacing: 0.5px !important;
}

.tc-stat {
  background: rgba(255, 255, 255, 0.04) !important;
  color: rgba(255, 255, 255, 0.2) !important;
  border: 1px solid rgba(255, 255, 255, 0.03) !important;
  border-radius: 2px !important;
  font-size: 9px !important;
  padding: 1px 10px !important;
  letter-spacing: 0.8px !important;
  font-family: "Courier New", monospace !important;
  transform: rotate(var(--stat-rot, 0deg)) !important;
}

.tc-stat:nth-child(1) { --stat-rot: -1.2deg; }
.tc-stat:nth-child(2) { --stat-rot: 1.8deg; }
.tc-stat:nth-child(3) { --stat-rot: -0.5deg; }
.tc-stat:nth-child(4) { --stat-rot: 2.3deg; }

.tc-stat[data-label="page"] {
  color: rgba(135, 206, 235, 0.35) !important;
  border-color: rgba(135, 206, 235, 0.06) !important;
}

.tc-stat[data-label="words"] {
  color: rgba(255, 200, 150, 0.3) !important;
  border-color: rgba(255, 200, 150, 0.04) !important;
}

.tc-stat[data-label="date"] {
  color: rgba(200, 220, 255, 0.25) !important;
  border-color: rgba(200, 220, 255, 0.04) !important;
}

.tc-stat[data-label="time"] {
  color: rgba(255, 255, 255, 0.15) !important;
  border-color: rgba(255, 255, 255, 0.03) !important;
}

/* 头像框 */
.tc-avatar-frame {
  border-radius: 4px !important;
  border: 2px solid rgba(255, 255, 255, 0.06) !important;
  background: rgba(255, 255, 255, 0.03) !important;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.04) !important;
  transform: rotate(var(--avatar-rot, 2deg)) !important;
  transition: transform 0.2s ease !important;
  padding: 3px !important;
}

.tm-para-char:nth-child(odd) .tc-avatar-frame { --avatar-rot: 2.5deg; }
.tm-para-char:nth-child(even) .tc-avatar-frame { --avatar-rot: -1.8deg; }
.tm-para-char:nth-child(3n) .tc-avatar-frame { --avatar-rot: 3.2deg; }

.tc-avatar-frame:hover {
  transform: rotate(0deg) scale(1.02) !important;
  border-color: rgba(255, 255, 255, 0.12) !important;
}

.tc-avatar-img {
  border-radius: 3px !important;
  filter: saturate(0.85) contrast(1.05) !important;
}

/* 分隔线 */
.tc-divider {
  border-color: rgba(255, 255, 255, 0.06) !important;
}

.tc-divider-text::before {
  color: rgba(255, 255, 255, 0.15) !important;
  font-size: 9px !important;
  letter-spacing: 3px !important;
}

/* ===== 用户消息卡片（云朵气泡-镜像） ===== */
.tm-para-user {
  background: rgba(255, 255, 255, 0.05) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border: 1px solid rgba(255, 255, 255, 0.06) !important;
  border-radius: 50px 50px 8px 50px !important;
