}

.tm-para-user:nth-child(1) .tm-body-user { --text-rot-user: -0.4deg; }
.tm-para-user:nth-child(2) .tm-body-user { --text-rot-user: 0.7deg; }
.tm-para-user:nth-child(3) .tm-body-user { --text-rot-user: -0.3deg; }
.tm-para-user:nth-child(4) .tm-body-user { --text-rot-user: 0.5deg; }

/* ===== 输入区（底部便利贴） ===== */
.tm-compose {
