/* ===== 变量 ===== */



:root {

  --ao3-red: #900;

  --ao3-red-dark: #7a0000;

  --ao3-bg: #ece4da;

  --ao3-paper: #fffdfa;

  --ao3-paper-soft: #fcf8f4;

  --ao3-paper-2: #f4ece4;

  --ao3-text: #1f1f1f;

  --ao3-text-2: #2b2b2b;

  --ao3-soft: #555;

  --ao3-line: #d8c8bc;

  --ao3-line-dark: #c9b7aa;

  --ao3-quote: #f3e7dc;

  --ao3-link: #900;

  --ao3-link-hover: #b30000;

  --safe-top: env(safe-area-inset-top, 0px);

  --safe-bottom: env(safe-area-inset-bottom, 0px);

}



/* ===== 全局 ===== */



#this-moment-screen {

  background: var(--ao3-bg) !important;

  color: var(--ao3-text) !important;

  font-family:

    Georgia,

    "Noto Sans CJK SC",

    "Noto Sans SC",

    "Source Han Sans SC",

    "PingFang SC",

    "Hiragino Sans GB",

    "Microsoft YaHei",

    sans-serif !important;

  font-synthesis: none !important;

}



.tm-bg-overlay {

  background:

    linear-gradient(to bottom, rgba(255,255,255,.16), rgba(255,255,255,.08)),

    var(--ao3-bg) !important;

}



.tm-bg-image {

  display: none !important;

}



/* ===== 顶栏 ===== */



.tm-header {

  position: relative !important;

  display: grid !important;

  grid-template-columns: auto 1fr auto !important;

  grid-template-rows: 42px 36px !important;

  grid-template-areas:

    "left left right"

    "chars chars chars" !important;

  column-gap: 8px !important;

  row-gap: 0 !important;

  align-items: center !important;

  padding: var(--safe-top) 0 0 0 !important;

  min-height: calc(var(--safe-top) + 78px) !important;

  border-bottom: none !important;

  box-sizing: border-box !important;

  overflow: hidden !important;

  z-index: 30 !important;

  background: linear-gradient(

    to bottom,

    #fdfbf7 0,

    #fdfbf7 calc(var(--safe-top) + 42px),

    var(--ao3-red) calc(var(--safe-top) + 42px),

    var(--ao3-red) 100%

  ) !important;

  box-shadow: inset 0 2px 0 #900 !important;

}



.tm-header::after {

