/* ==================================================
   🎴 黑白漫画 · 终极定稿版
   最后修订：宽气泡 / 无emoji / 报刊数字 / 极简动效
   ================================================== */

:root {
  --white: #fefef7;
  --black: #1a1a1a;
  --gray-dark: #2a2a2a;
  --shadow-sharp: 4px 4px 0px rgba(0,0,0,0.2);
}

/* 1. 背景（网点纸 + 轻微做旧） */
#this-moment-screen {
  background: var(--white) !important;
}
.tm-bg-overlay {
  background: repeating-linear-gradient(45deg, rgba(0,0,0,0.1) 0px, rgba(0,0,0,0.1) 1px, transparent 1px, transparent 8px),
              repeating-linear-gradient(-45deg, rgba(0,0,0,0.05) 0px, rgba(0,0,0,0.05) 1px, transparent 1px, transparent 12px),
              repeating-linear-gradient(0deg, rgba(0,0,0,0.02) 0px, rgba(0,0,0,0.02) 2px, transparent 2px, transparent 6px) !important;
  backdrop-filter: none;
}
.tm-bg-image {
  display: none !important;
}
.tc-watermark {
  display: block !important;
  background-image: repeating-linear-gradient(0deg, transparent, transparent 32px, rgba(0,0,0,0.08) 32px, rgba(0,0,0,0.08) 34px),
                    repeating-linear-gradient(90deg, transparent, transparent 32px, rgba(0,0,0,0.06) 32px, rgba(0,0,0,0.06) 34px) !important;
  background-size: 34px 34px;
  opacity: 0.6;
  mix-blend-mode: multiply;
}
.tc-watermark::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 20% 30%, rgba(0,0,0,0.02) 0%, transparent 70%);
  pointer-events: none;
}

/* 2. 顶栏（极简小字） */
.tm-header {
  background: var(--black) !important;
  border-bottom: 3px solid var(--white);
  position: relative;
  box-shadow: inset 0 -1px 0 rgba(255,255,255,0.2), 0 4px 8px rgba(0,0,0,0.1);
}
.tm-header::before {
  content: "";
  position: absolute;
  bottom: -6px;
  left: 10%;
  width: 80%;
  height: 3px;
  background: repeating-linear-gradient(90deg, var(--white), var(--white) 6px, transparent 6px, transparent 12px);
  pointer-events: none;
}
.tm-header-name {
  font-family: 'Courier New', 'Impact', monospace;
  font-weight: 900;
  letter-spacing: 0.5px;
  color: var(--white) !important;
  text-transform: uppercase;
  font-size: 11px !important;
  background: var(--black);
  display: inline-block;
  padding: 2px 6px;
  border: 1px solid var(--white);
  box-shadow: 2px 2px 0px rgba(0,0,0,0.3);
  max-width: 150px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tm-header-right {
  background: rgba(255,255,255,0.1);
  padding: 2px 8px;
  border-radius: 0;
  font-size: 10px;
  font-family: monospace;
}
.tm-btn-icon {
  color: #ccc !important;
  transition: 0.1s;
}
.tm-btn-icon:hover {
  color: var(--white) !important;
  transform: scale(1.1);
}

/* 3. 头像 */
.tc-avatar-frame {
  width: 56px !important;
  height: 56px !important;
  border-radius: 50% !important;
  background: var(--white);
  border: 3px solid var(--black);
  box-shadow: var(--shadow-sharp);
}
.tc-avatar-img {
  border-radius: 50%;
  filter: grayscale(100%) contrast(1.2);
}
.tc-avatar-badge {
  background: var(--black);
  color: var(--white);
  font-family: monospace;
  font-weight: bold;
  border-radius: 0;
  padding: 2px 8px;
  font-size: 9px;
}

/* 昵称行 */
.tc-meta-title {
  font-family: 'Courier New', monospace;
  font-weight: 900;
  font-size: 13px;
  color: var(--black);
  margin-bottom: 4px;
}

/* 4. 大字报风格数字（纯黑白，无电影票根词） */
.tc-meta-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}
.tc-stat {
  background: var(--black);
  color: var(--white);
  font-family: 'Courier New', monospace;
  font-weight: 900;
  font-size: 10px;
  padding: 3px 8px;
  border: 1px solid var(--white);
  box-shadow: 2px 2px 0px rgba(0,0,0,0.3);
  letter-spacing: 0.5px;
  text-transform: uppercase;
}
/* 完全自定义内容 - 无 emoji，纯文字 */
.tc-stat[data-label="page"]::before {
  content: "号外 ";
}
.tc-stat[data-label="page"]::after {
  content: " 期";
}
.tc-stat[data-label="words"]::before {
  content: "字数 ";
}
.tc-stat[data-label="date"]::before {
  content: "日期 ";
}
.tc-stat[data-label="time"]::before {
  content: "时间 ";
}
/* 清理可能的后缀 */
.tc-stat[data-label="words"]::after,
.tc-stat[data-label="date"]::after,
.tc-stat[data-label="time"]::after {
  content: "";
}
.tc-stat[data-label] {
  background: var(--black);
  color: var(--white);
}

/* 5. 气泡（宽度 96%，无尖角，小竖线指示） */
.tm-para-char,
.tm-para-user {
  background: transparent !important;
  margin: 18px 10px;
  position: relative;
}
.tm-body-char,
.tm-body-user {
  background: var(--white) !important;
  border: 3px solid var(--black);
  padding: 10px 22px;
  font-size: 12px !important;
  line-height: 1.6;
  color: var(--black);
  font-family: 'Courier New', 'MS Gothic', monospace;
  font-weight: 600;
  box-shadow: var(--shadow-sharp);
  position: relative;
  width: auto;
  max-width: 96%;
  min-width: 70%;
  box-sizing: border-box;
}
.tm-body-char {
  border-radius: 12px 28px 28px 12px;
  margin-right: auto;
}
.tm-body-char::before {
  content: "";
  position: absolute;
  left: -6px;
  top: 18px;
  width: 4px;
  height: 12px;
  background: var(--black);
  border-radius: 2px;
}
.tm-body-user {
  border-radius: 28px 12px 12px 28px;
  margin-left: auto;
}
.tm-body-user::before {
  content: "";
  position: absolute;
  right: -6px;
  top: 18px;
  width: 4px;
  height: 12px;
  background: var(--black);
  border-radius: 2px;
}
.tm-body-char::after,
.tm-body-user::after {
  content: none;
}

/* 引用块 */
.tm-quote-block {
  border-left: 5px solid var(--black);
  background: #f5f5f5;
  padding: 6px 12px;
  margin: 8px 0;
}
.tm-bold { font-weight: 900; text-decoration: underline; text-decoration-thickness: 2px; }
.tm-action { font-style: italic; border-bottom: 2px dotted var(--black); }
.tm-del { text-decoration: line-through double; }
.tm-load-more {
  background: var(--black);
  color: var(--white);
  border: none;
  font-family: monospace;
  font-weight: bold;
  padding: 6px;
  box-shadow: var(--shadow-sharp);
  font-size: 12px;
}

/* 6. 底栏（按键无 emoji） */
.tm-compose {
  background: var(--white) !important;
  border-top: 3px solid var(--black);
  padding: 12px;
  position: relative;
}
.tm-compose::before {
  content: "▼";
  position: absolute;
  top: -14px;
  left: 20px;
  font-size: 14px;
  color: var(--black);
  background: var(--white);
  padding: 0 4px;
}
.tm-input {
  background: var(--white);
  border: 2px solid var(--black);
  border-radius: 0;
  padding: 8px 14px;
  font-family: monospace;
  font-size: 12px;
  font-weight: bold;
}
.tm-input::placeholder {
  color: #888;
}
.tm-send-btn {
  background: var(--black);
  color: var(--white);
  border: none;
  border-radius: 0;
  padding: 6px 24px;
  font-family: 'Impact', monospace;
  font-weight: bold;
  font-size: 14px;
  letter-spacing: 1px;
  box-shadow: var(--shadow-sharp);
  transition: 0.05s linear;
}
.tm-send-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px black;
}
.tm-compose-toolbar {
  background: #e0e0e0;
  border: 2px solid var(--black);
  border-radius: 0;
  padding: 4px 12px;
  display: flex;
  gap: 8px;
}
.tm-regen-btn, .tm-suggestions-btn {
  background: var(--white);
  border: 2px solid var(--black);
  border-radius: 0;
  font-family: monospace;
  font-weight: bold;
  font-size: 11px;
  color: var(--black);
  padding: 4px 12px;
  box-shadow: 2px 2px 0px rgba(0,0,0,0.2);
  transition: 0.05s linear;
}
.tm-regen-btn:hover, .tm-suggestions-btn:hover {
  transform: translate(-1px, -1px);
  box-shadow: 3px 3px 0px black;
}
.tm-regen-btn:active, .tm-suggestions-btn:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}
.tm-regen-btn.active {
  background: var(--black);
  color: var(--white);
  box-shadow: none;
}
.tm-suggestions-panel {
  background: var(--white);
  border: 2px solid var(--black);
}
.tm-suggestion-item {
  border-left: 4px solid var(--black);
  background: #fafafa;
}
.tm-voice-btn {
  background: #ccc;
  border: 2px solid black;
  border-radius: 0;
  color: black;
  font-weight: bold;
  padding: 2px 8px;
}
.tm-translation-section {
  border-left-color: var(--black);
}

/* 7. 轻量动画（不卡顿） */
.tm-para {
  animation: popManga 0.2s cubic-bezier(0.34, 1.2, 0.64, 1);
}
@keyframes popManga {
  0% { opacity: 0; transform: scale(0.96) translateY(8px); }
  100% { opacity: 1; transform: scale(1) translateY(0); }
}
.tm-para-char:hover .tm-body-char,
.tm-para-user:hover .tm-body-user {
  transform: translateY(-2px);
  box-shadow: 6px 6px 0px var(--black);
  transition: transform 0.1s ease, box-shadow 0.1s ease;
}
.tm-stream-cursor {
  background: var(--black) !important;
  width: 2px !important;
  animation: blinkManga 0.8s step-end infinite;
}
@keyframes blinkManga {
  0%,100% { opacity: 1; }
  50% { opacity: 0; }
}
.tm-para.tm-streaming .tm-para-block {
  animation: textShake 0.1s infinite alternate;
}
@keyframes textShake {
  from { transform: translateX(0); }
  to { transform: translateX(1px); }
}
.tm-send-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px black;
  transition: 0.02s linear;
}
.tm-story::-webkit-scrollbar {
  width: 6px;
}
.tm-story::-webkit-scrollbar-track {
  background: var(--white);
  border-left: 1px solid var(--black);
}
.tm-story::-webkit-scrollbar-thumb {
  background: repeating-linear-gradient(45deg, var(--black), var(--black) 4px, var(--white) 4px, var(--white) 8px);
  border-radius: 0;
}

/* 8. 隐藏多余装饰 */
.tc-divider, .tc-header-deco, .tc-avatar-overlay,
.tc-meta-extra-1, .tc-meta-extra-2 {
  display: none !important;
}

/* 9. 动效关闭兼容 */
#this-moment-screen.tm-no-animations .tm-para,
#this-moment-screen.tm-no-animations .tm-para.tm-streaming .tm-para-block,
#this-moment-screen.tm-no-animations .tm-para-char:hover .tm-body-char,
#this-moment-screen.tm-no-animations .tm-para-user:hover .tm-body-user {
  animation: none !important;
  transform: none !important;
}

